import * as mongoose from 'mongoose';
import {ITeamBilling} from '../../interfaces/teamBilling.interface';


export interface ITeamBillingModel extends ITeamBilling, mongoose.Document {}

const teamBillingSchema = new mongoose.Schema({
  team: {
    type: mongoose.Schema.Types.ObjectId,
    ref: 'Team'
  },
  checklistPrice: {
    type: Number,
    default: 0
  },
  inventoryPrice: {
    type: Number,
    default: 0
  },
  active: {
    type: Boolean,
    default: false
  }
}, {
  timestamps: true
});


const TeamBilling = mongoose.model<ITeamBillingModel>('TeamBilling', teamBillingSchema);

export default TeamBilling;
